"""Round-2 lowercase-name TEST SET, generated by Gemini (docs/decisions.md Day 3.13). AI-drafted, not reviewed by the owner.

    python ml/data/gen_lowercase_gemini.py generate     # calls Gemini (needs GEMINI_API_KEY in .env), archives raw outputs
    python ml/data/gen_lowercase_gemini.py build        # mechanical filters -> ml/data/pii_names_lowercase_r2.jsonl (+ drop log)

Written and run BEFORE any word list was built or any approach run. The set is sealed: it is not used for lists, parameters or code.
Privacy: the key is read from .env and sent in a header; it is never printed or logged. The prompts contain no personal or project data.
Prompts are below, unchanged after the first call. Raw responses are archived in ml/data/lowercase_gemini/ (one file per call).
"""
from __future__ import annotations

import json
import re
import sys
import time
from pathlib import Path

import httpx

ROOT = Path(__file__).resolve().parents[2]
RAW = Path(__file__).parent / "lowercase_gemini"
OUT = Path(__file__).parent / "pii_names_lowercase_r2.jsonl"
MODEL = "gemini-3.1-flash-lite"          # the model the backend already uses
URL = f"https://generativelanguage.googleapis.com/v1beta/models/{MODEL}:generateContent"

STYLE = (
    "These are casual chat messages as people type them on a phone: NO capital letters anywhere (not even at the start of the sentence or "
    "for names), little or no punctuation, abbreviations like pls, thx, u are fine. Hinglish means Hindi written in the Roman alphabet mixed "
    "with English (for example 'kal meeting hai', 'mujhe bata dena'), never Devanagari script. Every sentence must be different in structure "
    "and topic. Return ONLY a JSON array."
)

POS_BASE = (
    "Write {n} chat messages that each mention at least one PERSON'S NAME (a real-sounding first name, sometimes first and last name) written "
    "entirely in lowercase. " + STYLE + " For each message return an object with: \"text\" (the message), \"names\" (list of the person names "
    "exactly as they appear in the text), and \"kind\": \"cue\" if the name comes right after or before a word that signals a person (for "
    "example tell, call, ask, hi, dear, 'ne', 'ko', 'ji', 'bhaiya', said, 'name is'), \"no_cue\" if the name just sits in the sentence "
    "without such a word, or \"word_name\" if the name is also an ordinary everyday word (for example rose, joy, will, mark, grace, deep). "
)
POS_THEMES = [
    "Focus: Indian first and last names (north and south Indian, Muslim, Sikh, Christian), messages written in English.",
    "Focus: Hinglish messages with Indian names, about everyday things (office, family, travel, food, exams, money).",
    "Focus: common English and international first names (British, American, European), casual English messages, plus some with full names.",
    "Focus: a balanced mix; make about half of them 'no_cue' messages, and include about five 'word_name' messages with names that are also everyday words.",
]
NEG_BASE = (
    "Write {n} chat messages that contain NO person's name at all. " + STYLE + " Each message is an object with \"text\" and \"names\" (always an "
    "empty list) and \"category\". "
)
NEG_THEMES = [
    "Category \"word_that_can_be_a_name\": messages that use ordinary words which are also sometimes first names, in their ordinary meaning "
    "(for example rose, joy, grace, deep, mark, will, summer, ruby, pooja as in the act of worship); and category \"place\": messages about cities, "
    "states, countries and landmarks.",
    "Category \"brand\": messages about companies, apps, shops and products; category \"date_festival\": messages about months, weekdays, festivals "
    "and holidays (including Indian ones).",
    "Category \"hinglish_plain\": everyday Hinglish messages about chores, work, food, travel and money, with no names at all.",
    "Category \"generic\": questions and requests to an AI assistant (recipes, coding help, travel plans, study help, summaries, "
    "translations), in English or Hinglish, with no names at all.",
]
CALLS = [("pos", i, POS_BASE.format(n=25) + t) for i, t in enumerate(POS_THEMES)] + [("neg", i, NEG_BASE.format(n=25) + t) for i, t in enumerate(NEG_THEMES)]


def api_key() -> str:
    from dotenv import dotenv_values

    key = dotenv_values(ROOT / ".env").get("GEMINI_API_KEY")
    if not key:
        sys.exit("GEMINI_API_KEY not found in .env")
    return key


def generate() -> None:
    RAW.mkdir(exist_ok=True)
    key = api_key()
    for kind, i, prompt in CALLS:
        f = RAW / f"{kind}_{i}.json"
        if f.exists():
            print(f"{f.name}: already archived, skipping")
            continue
        payload = {
            "contents": [{"role": "user", "parts": [{"text": prompt}]}],
            "generationConfig": {"temperature": 1.0, "maxOutputTokens": 8192, "responseMimeType": "application/json"},
        }
        for attempt in range(3):
            r = httpx.post(URL, headers={"x-goog-api-key": key}, json=payload, timeout=120)
            print(f"{f.name}: HTTP {r.status_code} (attempt {attempt + 1})")
            if r.status_code == 200:
                break
            time.sleep(5 * (attempt + 1))
        else:
            sys.exit(f"{f.name}: failed after 3 attempts (HTTP {r.status_code})")
        f.write_text(json.dumps({"prompt": prompt, "model": MODEL, "response": r.json()}, indent=1), encoding="utf-8")


# ---------------------------------------------------------------- build: mechanical filters only
norm = lambda t: re.sub(r"\s+", " ", t).strip().lower()
toks = lambda t: set(re.findall(r"[a-z]+", t.lower()))


def jaccard(a: set, b: set) -> float:
    return len(a & b) / len(a | b) if a and b else 0.0


def reference_texts() -> list[str]:
    """Everything the new test set must not duplicate: round-1 set, existing names sample, Hinglish-TOP TRAIN queries."""
    import pandas as pd
    from huggingface_hub import hf_hub_download

    out = []
    for f in ("pii_names_lowercase.jsonl", "pii_names_sample.jsonl"):
        out += [json.loads(l)["text"] for l in (Path(__file__).parent / f).read_text(encoding="utf-8").splitlines() if l.strip()]
    tr = pd.read_parquet(hf_hub_download("WillHeld/hinglish_top", "data/train-00000-of-00001-edd2764b201a5c1f.parquet", repo_type="dataset"))
    out += tr.cs_query.tolist() + tr.en_query.tolist()
    return out


def build() -> None:
    ref = reference_texts()
    ref_n = {norm(t) for t in ref}
    ref_tok = [toks(t) for t in ref]
    drops: list[dict] = []
    kept: dict[str, list[dict]] = {"pos": [], "neg": []}
    seen: list[tuple[str, set]] = []
    for kind, i, _ in CALLS:
        data = json.loads((RAW / f"{kind}_{i}.json").read_text(encoding="utf-8"))
        text = "".join(p.get("text", "") for p in data["response"]["candidates"][0]["content"]["parts"])
        try:
            items = json.loads(text)
        except json.JSONDecodeError:
            drops.append({"call": f"{kind}_{i}", "reason": "unparseable response"})
            continue
        for k, it in enumerate(items):
            t = it.get("text", "") if isinstance(it, dict) else ""
            names = it.get("names", []) if isinstance(it, dict) else []
            why = None
            if not isinstance(t, str) or not t.strip() or not isinstance(names, list) or not all(isinstance(n, str) for n in names):
                why = "malformed"
            elif t != t.lower():
                why = "not all lowercase"
            elif len(t) < 5 or len(t) > 220:
                why = "length"
            elif kind == "pos" and (not names or any(n != n.lower() or n not in t for n in names)):
                why = "name missing / not lowercase / not a substring"
            elif kind == "pos" and any(len(re.findall(rf"(?<![a-z]){re.escape(n)}(?![a-z])", t)) != len(re.findall(re.escape(n), t)) for n in names):
                why = "name also occurs inside another word"
            elif kind == "neg" and names:
                why = "negative has names"
            elif norm(t) in ref_n or any(jaccard(toks(t), r) >= 0.8 for r in ref_tok):
                why = "duplicate of a round-1 / existing / Hinglish-TOP train sentence"
            elif any(norm(t) == s or jaccard(toks(t), st) >= 0.8 for s, st in seen):
                why = "duplicate within the new set"
            if why:
                drops.append({"call": f"{kind}_{i}", "index": k, "text": t, "reason": why})
                continue
            seen.append((norm(t), toks(t)))
            kept[kind].append({"set": kind, "category": (it.get("kind") if kind == "pos" else it.get("category")) or "unlabelled", "text": t.strip(), "names": names,
                               "call": f"{kind}_{i}"})
    manual = {}
    mp = Path(__file__).parent / "lowercase_gemini" / "manual_drops.json"
    if mp.exists():
        manual = {d["text"]: d["reason"] for d in json.loads(mp.read_text(encoding="utf-8"))}
    rows = []
    for kind in ("pos", "neg"):
        keep = []
        for r in kept[kind]:
            if r["text"] in manual:
                drops.append({"call": r["call"], "text": r["text"], "reason": f"manual: {manual[r['text']]}"})
            else:
                keep.append(r)
        # deterministic and balanced across the 4 prompts of each side: the first 15 surviving rows of each prompt (4 x 15 = 60).
        # (A first version took the first 60 in call order, which would have dropped most of the prompt that asks for "no_cue" sentences.)
        per_call: dict[str, int] = {}
        for r in keep:
            per_call[r["call"]] = per_call.get(r["call"], 0) + 1
            if per_call[r["call"]] <= 15:
                rows.append(r)
            else:
                drops.append({"call": r["call"], "text": r["text"], "reason": "surplus beyond 15 per prompt"})
    for n, r in enumerate(rows, 1):
        r["id"] = n
    OUT.write_text("\n".join(json.dumps({k: r[k] for k in ("id", "set", "category", "text", "names", "call")}, ensure_ascii=False) for r in rows) + "\n", encoding="utf-8")
    (RAW / "drops.json").write_text(json.dumps(drops, indent=1, ensure_ascii=False), encoding="utf-8")
    from collections import Counter

    print(len(rows), "rows:", Counter((r["set"], r["category"]) for r in rows))
    print("drops:", Counter(d["reason"].split(":")[0] for d in drops))


if __name__ == "__main__":
    {"generate": generate, "build": build}[sys.argv[1] if len(sys.argv) > 1 else "build"]()
